    "audit_result": {
      "property_id": "PROP-01b-partial-asm-002",
      "classification": "potential-vulnerability",
      "code_path": "src/sales/LegionAbstractSale.sol::transferInvestorPositionWithAuthorization::L524-546",
      "proof_trace": "`_verifyTransferSignature` (LegionPositionManager.sol:L161) hashes `(from, to, positionId, msg.sender, address(this), chainId)` \u2014 no nonce and no deadline. ERC721 ownership provides implicit one-time-use protection under normal flow, but the admin `transferInvestorPosition` (onlyLegion, no signature) can return a position to `from`, after which the original authorization signature is fully replayable with no expiry. Other functions in the same codebase (`LegionPreLiquidApprovedSale`, `LegionCapitalRaise`) use an explicit `s_usedSignatures` mapping for replay protection; this function lacks an equivalent.",
      "attack_scenario": "Legion admin issues a transfer authorization for (Alice \u2192 Bob, positionId=5); after the transfer is consumed, admin calls `transferInvestorPosition(Bob, Alice, 5)` to return the position; `Caller1` then replays the original signature via `transferInvestorPositionWithAuthorization(Alice, Bob, 5, sig)`, which passes all checks and re-executes the transfer without a new authorization.",
      "checklist_id": "PROP-01b-partial-asm-002"
    },
    "text": "transferInvestorPositionWithAuthorization signature includes replay protection (nonce/deadline).",
    "assertion": "forall authSig: authSig.params include (nonce OR deadline) preventing cross-context replay",
    "covers": "SG-013",
    "severity": "HIGH",
    "type": "assumption"
  }
}

